package com.canteen.management.repository;import java.util.List;import java.util.Optional;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.stereotype.Repository;import com.canteen.management.entity.Order;@Repositorypublic interface OrderRepository extends JpaRepository<Order, Long> {    Optional<Order> findByOrderNumber(String orderNumber);    java.util.List<Order> findByStudentId(String studentId);    java.util.List<Order> findByCanteenId(String canteenId);    Long countByCanteenId(String canteenId);    @Query("SELECT SUM(o.totalPrice) FROM Order o")    Double getTotalRevenue();    Long countByFoodId(Long foodId);    Long countByBranchId(Long branchId);    Long countByBranchIdAndStatus(Long branchId,String status);    @Query("""SELECT o.foodIdFROM Order oGROUP BY o.foodIdORDER BY COUNT(o.foodId) DESC""")    List<Long> getMostOrderedFoodIds();    @Query("""SELECT COALESCE(SUM(o.totalPrice),0)FROM Orders oWHERE o.branchId=:branchId""")    Double getTotalRevenue(Long branchId);}